/* @lc app=leetcode id=3203 lang=kotlin */ class Solution { fun far(g: Map<Int, List<Int>>, n: Int, s: Int): Pair<Int, Int> = IntArray(n) { -1 }.also { it[s] = 0 }.let { d -> generateSequence(listOf(s)) { f -> f.flatMap { u -> g[u].orEmpty().filter { d[it] == -1 }.onEach { v -> d[v] = d[u] + 1 } }.takeIf { it.isNotEmpty() } }.toList().let { lv -> lv.last()[0] to lv.size - 1 } } fun diam(e: Array<IntArray>): Int = e.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> far(g, e.size + 1, far(g, e.size + 1, 0).first).second } fun minimumDiameterAfterMerge(edges1: Array<IntArray>, edges2: Array<IntArray>): Int = diam(edges1).let { a -> diam(edges2).let { b -> maxOf(a, b, (a + 1) / 2 + (b + 1) / 2 + 1) } } }